llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Vismodegib, a lipophilic hedgehog inhibitor with an aryl amide/heteroaromatic core, has an absolute oral bioavailability of 31.8% in humans after a 150 mg oral dose, directly supporting F ≥ 20% for a similarly lipophilic, poorly soluble kinase-inhibitor-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Belumosudil, an oral kinase inhibitor containing amide and heteroaromatic groups, shows 64% absolute bioavailability after a 200 mg single oral dose in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Glafenine has a mean absolute bioavailability of approximately 0.33 in healthy volunteers, providing direct human evidence for F ≥ 20% in a moderately lipophilic, heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Sorafenib absolute bioavailability is reported as 50% under fasted conditions, directly matching the fasted query condition and supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Sorafenib has also been reported with limited oral bioavailability of approximately 8.5% in humans, providing a contradictory low-bioavailability anchor; however, other sorafenib records report 38–49% and 50%, and the low value likely reflects formulation/dose effects.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "CJ-13,610, a structurally related aryl thioether/azole, showed a relative bioavailability of 47% in humans derived from intravenous and oral clinical studies, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most retrieved experimental evidence, including direct human absolute bioavailability measurements for vismodegib (31.8%), belumosudil (64%), glafenine (33%), sorafenib under fasted conditions (50%), and CJ-13,610 (47%), supports F ≥ 20%. The only clearly low value (sorafenib ~8.5%) is contradicted by other sorafenib records and likely reflects formulation/dose effects. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "Retrieved analogues have low-to-moderate Morgan similarity (0.19–0.26), limiting structural transferability.",
    "One retrieved record (C19) appears to pair a fenbendazole-like SMILES with fenofibrate text, so its relevance is uncertain and was not relied upon.",
    "Sorafenib records are conflicting (8.5% vs 38–50%), and the low value may reflect formulation/dose effects rather than intrinsic bioavailability.",
    "Fasted-state-specific data are limited; only sorafenib C31 explicitly reports fasted conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

